import numpy as np, wave, webrtcvad, json

def load(p):
    w = wave.open(p,'rb')
    assert w.getsampwidth()==2 and w.getnchannels()==1
    raw = w.readframes(w.getnframes())
    return raw, w.getframerate()

def vad_segments(path, agg=2, hangover=6, min_dur=0.1, merge_gap=0.25):
    raw, sr = load(path)
    vad = webrtcvad.Vad(agg)
    fl = int(0.02*sr)*2  # 20ms in bytes
    flags=[]
    n = len(raw)//fl
    for i in range(n):
        flags.append(1 if vad.is_speech(raw[i*fl:(i+1)*fl], sr) else 0)
    # hangover
    h = flags[:]
    run=0
    for i in range(n):
        if flags[i]: run=hangover
        elif run>0: h[i]=1; run-=1
    segs=[]; s=None
    for i in range(n):
        if h[i] and s is None: s=i
        if not h[i] and s is not None:
            segs.append((s*0.02, i*0.02)); s=None
    if s is not None: segs.append((s*0.02, n*0.02))
    # merge small gaps
    merged=[]
    for a,b in segs:
        if merged and a-merged[-1][1] <= merge_gap: merged[-1]=(merged[-1][0], b)
        else: merged.append((a,b))
    return [(round(a,3),round(b,3)) for a,b in merged if b-a>=min_dur]

for reel in [\"reel1\",\"reel2\"]:
